window.kbPageData["views/entry/k-1f8d4b3e86cc722a"] = {"key":"entry/k-1f8d4b3e86cc722a","state":{"route":"entry/k-1f8d4b3e86cc722a"},"node":{"id":"k-1f8d4b3e86cc722a","mode":"k","title":"蓝天保卫战的主战场与净土保卫战的重点","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["蓝天、碧水、净土保卫战"],"qs":["政治理论必刷100题#80"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["ecology"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["政治理论","生态环境"],"来源主题":["生态环境与能源"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"习近平在全国生态环境保护大会上的讲话提出，蓝天保卫战要以京津冀及周边、长三角、汾渭平原等重点区域为主战场，净土保卫战重在强化污染风险管控。","review":{"definition":"习近平在全国生态环境保护大会上的讲话提出，蓝天保卫战要以京津冀及周边、长三角、汾渭平原等重点区域为主战场，净土保卫战重在强化污染风险管控。","explanation":"第80题③所列三个区域符合讲话对大气污染治理主战场的部署。⑤所说的风险管控涵盖防止土壤新增污染，以及逐步解决长期积累的土壤和地下水严重污染问题，因此③、⑤均正确。","references":[],"evidence":"净土保卫战重在强化污染风险管控。","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"285d545a34d41ff8","label":"蓝天、碧水、净土保卫战","topic":"生态环境与能源","category":"非时政","text":"3.蓝天、碧水、净土保卫战\n持续深入打好蓝天保卫战。以京津冀及周边、长三角、汾渭平原等重点区域为主战场，\n以细颗粒物控制为主线，大力推进多污染物协同减排。\n持续深入打好碧水保卫战。统筹水资源、水环境、水生态治理，深入推进长江、黄河等\n大江大河和重要湖泊保护治理，优化调整水功能区划及管理制度。\n持续深入打好净土保卫战。开展土壤污染源头防控行动，严防新增污染，逐步解决长期\n积累的土壤和地下水严重污染问题。\n——《中共中央 国务院关于全面推进美丽中国建设的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":46,"last":46,"page":46,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#80":{"paper":"政治理论必刷100题","n":80,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",25],"asrc":["国省考政治理论必刷100题.pdf",83],"card":"c712792d79101a72fad0396e","links":[{"id":"k-1f8d4b3e86cc722a","role":"直接考查","why":"题目同时核对净土保卫战的污染风险管控要求和蓝天保卫战的主战场，后者包括京津冀及周边、长三角和汾渭平原。"}]}},"terms":{},"references":{},"topics":[{"slug":"ecology","title":"生态保护与绿色转型"}],"units":{"k-1f8d4b3e86cc722a":[["政治理论必刷100题#80"]]}};
